class Solution {
public:
    vector<string> res;
    string path;
    void go(int open, int close, int n) {
        if ((int)path.size() == 2 * n) {
            res.push_back(path);
            return;
        }
        if (open < n) {
            path.push_back('(');
            go(open + 1, close, n);
            path.pop_back();
        }
        if (close < open) {
            path.push_back(')');
            go(open, close + 1, n);
            path.pop_back();
        }
    }
    vector<string> generateParenthesis(int n) {
        go(0, 0, n);
        return res;
    }
};
